SELECT AVG(dragons) AS media_dragoes
FROM pro_games
WHERE year = 2026;

SELECT AVG(towers) AS media_torres_vencedoras
FROM pro_games
WHERE win = true;

SELECT COUNT(*) AS partidas
FROM (
  SELECT game_id FROM pro_games
  GROUP BY game_id
  HAVING SUM(kills) > 40
) s;

SELECT AVG(barons) AS media_barons_vencedoras
FROM pro_games
WHERE win;
